#include "fx3-date98-trace-core-v1.h"
static unsigned char*date98_trace;static unsigned date98_trace_attempted;
static U date98_now(void){struct ts t;if(clock_gettime(1,&t))return 0;return (U)t.s*1000000000UL+t.n;}
static void date98_bind_trace(void){if(date98_trace_attempted)return;date98_trace_attempted=1;char cmd[4096]={0};int f=open("/proc/cmdline",0);long n=f<0?-1:read(f,cmd,sizeof cmd-1);if(f>=0)close(f);if(n<=0||!strstr(cmd,"memrsv=0x00010000@0x41df00000:uc")){dprintf(2,"FX3_DATE98_TRACE_UNAVAILABLE reason=no_explicit_software_reserve\n");return;}f=open("/dev/mem",2);void*p=f<0?(void*)-1:mmap(0,DATE98_SPAN,3,1,f,DATE98_PHYS);if(f>=0)close(f);if(p!=(void*)-1&&d98_init(p,DATE98_SPAN)){date98_trace=p;dprintf(2,"FX3_DATE98_TRACE_BOUND physical=%#lx bytes=%lu record_size=%lu cap=%lu input_first4K_untouched=1 original_state_writes=0\n",DATE98_PHYS,DATE98_SPAN,DATE98_REC,DATE98_CAP);}else dprintf(2,"FX3_DATE98_TRACE_UNAVAILABLE reason=map_or_header errno=%d\n",*__errno_location());}
static int date98_read(int fd,U p,void*out,U n){return fd>=0&&p>=4096&&p<0x8000000000UL&&n<=0x8000000000UL-p&&pread(fd,out,n,p)==(long)n;}
static struct d98_model date98_model(const char *phase,U id,U pc){struct d98_model m={255,255,0,0xffffffffU,0xffffffffU,0};int fd=open("/proc/self/mem",0);unsigned char f[2];if(app_base&&date98_read(fd,app_base+0x8365c90,f,2)){m.force_current=f[0];m.force_next=f[1];m.force_valid=1;}if(app_base&&date98_read(fd,app_base+0x8227358,&m.date_current,4))m.date_mask|=1;if(app_base&&date98_read(fd,app_base+0x822735c,&m.date_next,4))m.date_mask|=2;int err=*__errno_location();if(fd>=0)close(fd);dprintf(2,"FX3_DATE98_LIVE phase=%s id=%lu pc=%#lx pid=%ld tid=%ld app_base=%#lx fresh_fd=%d read_errno=%d force_valid=%u force_current=%u force_next=%u date_mask=%u date_current=%u date_next=%u passive=1\n",phase,id,pc,syscall(172),syscall(178),app_base,fd,err,m.force_valid,m.force_current,m.force_next,m.date_mask,m.date_current,m.date_next);return m;}
static void date98_point(U id,U pc,U*r){int saved=*__errno_location();date98_model("original_point",id,pc);dprintf(2,"FX3_DATE98_POINT id=%lu pc=%#lx pid=%ld tid=%ld w0=%d w1=%u x0=%#lx x1=%#lx x19=%#lx x21=%#lx x24=%#lx x25=%#lx original_instruction_follows=1\n",id,pc,syscall(172),syscall(178),(int)(W)r[0],(W)r[1],r[0],r[1],r[19],r[21],r[24],r[25]);*__errno_location()=saved;}
static W date98_capture(void *request,W n,unsigned char out[64],int *read_errno){int fd=open("/proc/self/mem",0);int ok=n&&n<=64&&date98_read(fd,(U)request,out,n);*read_errno=*__errno_location();if(fd>=0)close(fd);if(ok)return 1;if(n==32&&request&&(U)request>=4096&&(U)request<=~0UL-32){/* Original native sync contract owns all32 until caller frees after return. */d98_copy(out,request,32);return 2;}return 0;}
static void date98_hex(char out[129],const unsigned char *p,W n){const char*h="0123456789abcdef";for(W i=0;i<n;i++){out[i*2]=h[p[i]>>4];out[i*2+1]=h[p[i]&15];}out[n*2]=0;}
static U date98_events;
static int date98_sync(int(*fn)(W,void*),W(*sizefn)(void*),W dst,void*request,U caller){int saved=*__errno_location();if(dst!=0x80900141U||!request){*__errno_location()=saved;return fn(dst,request);}U event=__atomic_add_fetch(&date98_events,1,__ATOMIC_RELAXED);W n=sizefn?sizefn(request):0;unsigned char before[64],after[64];char hex[129]={0};int err=0;W bm=event<=64?date98_capture(request,n,before,&err):0;date98_bind_trace();struct d98_model model=date98_model("sync_before",event,caller);U pid=syscall(172),tid=syscall(178);unsigned char*record=d98_begin(date98_trace,1,pid,tid,dst,n,(U)request,caller,before,bm!=0,bm,date98_now(),&model);if(bm)date98_hex(hex,before,n);dprintf(2,"FX3_DATE98_SYNC phase=before event=%lu pid=%lu tid=%lu destination=%#x pointer=%p caller=%#lx bytes=%u captured=%u read_method=%u pread_errno=%d raw=%s original_sync_delegated=1 caller_owns_until_return=1\n",event,pid,tid,dst,request,caller,n,bm!=0,bm,err,hex);int f=open("/tmp/fx3-date98-active.identity",0x80241,0600);if(f>=0){dprintf(f,"%lu %lu %lu %#lx %u\n",pid,tid,event,(U)request,n);close(f);}*__errno_location()=saved;int rc=fn(dst,request);int after_errno=*__errno_location();W am=event<=64?date98_capture(request,n,after,&err):0;model=date98_model("sync_after",event,caller);d98_end(record,rc,after_errno,after,n,am!=0,am,date98_now(),&model);hex[0]=0;if(am)date98_hex(hex,after,n);dprintf(2,"FX3_DATE98_SYNC phase=after event=%lu pid=%lu tid=%lu destination=%#x pointer=%p bytes=%u result=%d errno=%d captured=%u read_method=%u pread_errno=%d raw=%s body_unmodified_by_observer=1\n",event,pid,tid,dst,request,n,rc,after_errno,am!=0,am,err,hex);*__errno_location()=after_errno;return rc;}
